#include "Frequency.h"
#include <stdio.h>

void Frequency(int *result, int epsilon[N]) {
    int sum = 0;
    for (int i = 0; i < N; i++) {
        // Transform each 0 to -1 and 1 to 1
        int transformed = 2 * epsilon[i] - 1;
        sum += transformed;
    }
    *result = sum;
}
